const args: string[] = [
  'npx', 'playwright', 'test',
  `--config=${configPath}`,
];

// Device filter
if (input.device === 'android') {
  // mobile-chrome = the Pixel profile, rendered on Chromium
  args.push('--project=mobile-chrome');
} else if (input.device === 'ios') {
  // mobile-safari = the iPhone profile on WebKit, so iOS behaviour matches the real Safari engine
  args.push('--project=mobile-safari');
}
// 'all' runs both projects (default) — omitting --project lets every project in the config run

if (input.testFile) {
  // Narrow to a single spec while chasing one failure instead of running the whole suite
  args.push(input.testFile);
}

if (input.headed) {
  args.push('--headed');
}

const cmd = args.join(' ');
// Capture stdout (not inherit) so the run output is available to parse after Playwright exits
stdout = execSync(cmd, execOpts);

private parseResults(): MobileRunSummary {
  // The reporter overwrites step-results-latest.json each run — the canonical, most-recent result
  const latestPath = path.join(this.outputsDir, 'step-results-latest.json');

  if (!fs.existsSync(latestPath)) {
    // Fallback: no "latest" pointer, so pick the newest timestamped file by reverse-sorting the names
    const files = fs.readdirSync(this.outputsDir)
      .filter(f => f.startsWith('step-results-') && f.endsWith('.json'))
      .sort()
      .reverse();

    if (files.length === 0) {
      // Nothing at all means the reporter never ran — the results simply don't exist to parse
      throw new Error('No step results found. Did the mobile-step-reporter run?');
    }
    const content = fs.readFileSync(path.join(this.outputsDir, files[0]), 'utf-8');
    return JSON.parse(content);
  }

  const content = fs.readFileSync(latestPath, 'utf-8');
  return JSON.parse(content);
}

private buildSimulatorLinks(
  provider: SimulatorProvider,
  summary: MobileRunSummary
): Record<string, string> {
  // Look up the chosen provider's config (deep-link templates keyed by device)
  const config = SIMULATOR_PROVIDERS[provider];
  const links: Record<string, string> = {};

  for (const device of summary.devices) {
    // Device-specific deep link if the provider has one; else fall back to the provider's home page
    links[device] = config.baseUrls[device] || `https://${provider}.com`;
  }

  return links;
}

lines.push('#### Manual Verification');
const simLink = simulatorLinks[test.device];
// Human-friendly device name, falling back to the raw device id if unmapped
const deviceName = DEVICE_LABELS[test.device] || test.device;
// iOS repro must say Safari (WebKit); Android says Chrome — the browser the emulated device actually uses
const browserName = test.platform === 'ios' ? 'Safari' : 'Chrome';

lines.push(`**Open Online Simulator:** [${deviceName} on ${this.capitalize(input.simulator)}](${simLink})`);
lines.push('**Steps to reproduce:**');
lines.push(`1. Open the simulator link above (${deviceName})`);
lines.push(`2. In ${browserName}, navigate to: \`${appUrl}\``);
lines.push('3. Log in with test credentials');

// Steps 1-3 are fixed setup; the recorded test steps continue the numbering from 4
let manualStepNum = 4;
for (const step of test.steps) {
  // Skipped steps never executed, so they'd only confuse a manual tester — drop them
  if (step.status === 'skipped') continue;
  lines.push(`${manualStepNum}. ${step.name}`);
  manualStepNum++;
}

if (test.failedStep) {
  // Close the recipe with the exact broken step as Expected and its captured error as Actual
  lines.push(`${manualStepNum}. **Expected:** Step "${test.failedStep.name}" completes successfully`);
  lines.push(`${manualStepNum + 1}. **Actual:** ${test.failedStep.error?.message || 'Step failed'}`);
}

private generateRecommendations(summary: MobileRunSummary): string[] {
  const recs: string[] = [];
  if (summary.failed === 0) {
    // Nothing failed — short-circuit before any pattern matching
    recs.push('All mobile tests passed. The application is functioning correctly on both Android and iOS device profiles.');
    return recs;
  }

  // Partition failures by platform to tell a platform quirk from an app-level bug
  const androidFails = summary.failedTests.filter(t => t.platform === 'android');
  const iosFails = summary.failedTests.filter(t => t.platform === 'ios');

  if (androidFails.length > 0 && iosFails.length === 0) {
    // Fails on Android but not iOS → suspect Chrome/Chromium rendering or the Pixel viewport
    recs.push('Failures are Android-only. Investigate Chrome-specific rendering or viewport issues on the Pixel 5 profile.');
  } else if (iosFails.length > 0 && androidFails.length === 0) {
    // Mirror case → suspect Safari/WebKit behaviour or the iPhone viewport
    recs.push('Failures are iOS-only. Investigate Safari/WebKit-specific behavior or viewport issues on the iPhone 13 profile.');
  }

  // Orthogonal check: a timeout cluster points at slow mobile responses, regardless of platform
  const timeoutTests = summary.failedTests.filter(t => t.status === 'timedOut');
  if (timeoutTests.length > 0) {
    recs.push(`${timeoutTests.length} test(s) timed out. Mobile connections may be slower — consider optimizing response handling for mobile viewports.`);
  }

  return recs;
}
